<script setup>import {Head,Link,useForm} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Icon from '@/Components/UI/Icon.vue';import HrNav from '../Partials/HrNav.vue';import PlanningForm from './PlanningForm.vue';defineOptions({layout:AppLayout});const props=defineProps({shift:Object,employees:[Array,Object],departments:[Array,Object]});const local=v=>v?v.slice(0,16):'';const form=useForm({employee_uuid:props.shift.employee.uuid,department_uuid:props.shift.department_uuid??'',title:props.shift.title??'',starts_at:local(props.shift.starts_at),ends_at:local(props.shift.ends_at),observation:props.shift.observation??''});const submit=()=>form.put(`/administration/planning/${props.shift.uuid}`);</script><template><Head title="Modifier le planning"/><div class="space-y-5"><HrNav/><header class="flex gap-3"><Link href="/administration/planning" class="flex h-9 w-9 items-center justify-center rounded-lg border border-gray-200 bg-white"><Icon name="arrow-left"/></Link><div><p class="text-xs font-bold uppercase tracking-wide text-cyan-600">Planning</p><h1 class="font-heading text-2xl font-bold text-slate-800 dark:text-white">Modifier le créneau</h1><p class="font-mono text-xs text-slate-400">{{shift.uuid}}</p></div></header><PlanningForm :form="form" :employees="employees" :departments="departments" cancel-href="/administration/planning" submit-label="Enregistrer" @submit="submit"/></div></template>
